# --------------------------- MODEL -----------------------
@st.cache_resource
def load_model():
    if not MODEL.exists() or not LABELS.exists():
        return None, None
    import tensorflow as tf
    loaded = tf.keras.models.load_model(MODEL)
    class_names = json.loads(LABELS.read_text(encoding="utf-8"))
    return loaded, class_names

def predict(image):
    model, class_names = load_model()
    if model is None:
        return None, None, "Trained model missing. Check model/disease_model.keras and model/class_names.json."
    # Keep this input format aligned with the current model pipeline:
    # RGB image resized to 224x224; raw pixel values are passed to the model.
    image_array = np.asarray(
        image.convert("RGB").resize((224, 224)),
        dtype="float32"
    )
    scores = model.predict(np.expand_dims(image_array, axis=0), verbose=0)[0]
    best_index = int(np.argmax(scores))
    return (class_names[best_index], float(scores[best_index])), class_names, None

